// === Tab: mySketch ===
let font
let ribbon
let cassette
let cassetteInside
let gear
let spools
let label
let tapeShader
let plastic

async function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL)
	font = await loadFont("https://fonts.gstatic.com/s/storyscript/v3/mem5YaSw02SQ0OlzDuR8Isk-VeJoCqeDjg.ttf")

	tapeShader = baseMaterialShader().modify(() => {
		const t = uniformFloat(() => millis() * 0.005)
		getObjectInputs((inputs) => {
			let coord = inputs.position.xy
			const s = 0.01
			// coord += [10 * noise(coord.x*s, coord.y*s), 10 * noise(coord.x*s, coord.y*s, 123.456)]
			inputs.position.x += 10 * sin(inputs.texCoord.y * 3 + t * 0.01)
			inputs.position.y += 20 * sin(coord.x * 0.015 + t * 0.1 + coord.y * 0.002) // * coord.x * coord.x * 0.001
			return inputs
		})
	})

	plastic = baseMaterialShader().modify(() => {
		let pos = sharedVec3()
		getCameraInputs((inputs) => {
			pos = inputs.position
			return inputs
		})
		getPixelInputs((inputs) => {
			const toCam = normalize(-pos)
			const facingFront = abs(inputs.normal.z)
			inputs.color.a = pow(1 - facingFront, 1) * 0.8 + 0.05
			const reflected = reflect(toCam, inputs.normal)
			let c = abs(sin(reflected.x * 3 + sin(reflected.y * 3)))
			c = smoothstep(0.5, 0.6, c)
			inputs.color.xyz = [c, c, c] * 0.5 + 0.5
			inputs.ambientMaterial = inputs.color.xyz
			return inputs
		})
		combineColors(components => {
			return [
				components.baseColor * components.diffuse +
				components.ambientColor * components.ambient +
				components.specularColor * components.specular +
				components.emissive,
				components.opacity + max(max(components.specular.x, components.specular.y), components.specular.z)
			];
		});
	})

	label = createFramebuffer({
		width: 280,
		height: 40
	})
	label.draw(() => {
		rectMode(CENTER)
		noStroke()
		fill(240)
		rect(0, 0, label.width, label.height, 5)

		stroke(220)
		line(-label.width / 2, -label.height * 0.3, label.width / 2, -label.height * 0.3)
		line(-label.width / 2, label.height * 0.3, label.width / 2, label.height * 0.3)

		noStroke()
		textFont(font)
		textSize(30)
		fill('rgb(68,42,162)')
		textAlign(CENTER, CENTER)
		text('p5.js 2.2', 0, 0)
	})

	const path = buildGeometry(() => {
		noFill()

		const pts = []
		curveDetail(0.06)
		pts.push(createVector(100, height / 2 + 100))
		pts.push(createVector(0, height / 2))
		pts.push(createVector(-width / 3, height / 2 + 50))
		pts.push(createVector(-width / 3, height / 2 - 100))
		for (let i = 0; i < 40; i++) {
			const prev = pts.at(-1)
			const prevPrev = pts.at(-3)
			const off = width * random(0.2, 0.4)
			pts.push(createVector(-Math.sign(prev.x) * off, prevPrev.y - 5))
			pts.push(createVector(-Math.sign(prev.x) * off, prev.y - random(40, 60)))
		}

		beginShape()
		for (const pt of pts) {
			splineVertex(pt.x, pt.y)
		}
		endShape()
	})

	textureMode(NORMAL)
	ribbon = buildGeometry(() => {
		var pts = [path.vertices[path.edges[0][0]]]
		for (const edge of path.edges) {
			pts.push(path.vertices[edge[1]])
		}
		const dists = [0]
		for (let i = 1; i < pts.length; i++) {
			dists.push(
				dists.at(-1) + pts[i - 1].dist(pts[i])
			)
		}
		beginShape(QUAD_STRIP)
		for (let i = 0; i < pts.length; i++) {
			for (const z of [1, -1]) {
				const u = map(z, -1, 1, 0, 1)
				const v = map(dists[i], 0, dists.at(-1), 0, 1)
				vertex(pts[i].x, pts[i].y, z * 50, u, v)
			}
		}
		endShape()
	})
	ribbon.computeNormals()
	ribbon.normalize()

	const cs = 1
	const outerCassette = roundedCube(300 * cs, 300 / 4.25 * 2.75 * cs, 20 * cs, 5 * cs)
	cassette = csg(() => {
			// box(300, 300 / 4.25 * 2.75, 20)
			scale(1 / cs)
			model(outerCassette)
		})
		.subtract(() => {
			translate(-60, 0)
			rotateX(PI / 2)
			cylinder(18, 30)
		})
		.subtract(() => {
			translate(60, 0)
			rotateX(PI / 2)
			cylinder(18, 30)
		})
		.done()

	spools = csg(() => {
			translate(-60, 0)
			rotateX(PI / 2)
			cylinder(65, 12)
		})
		.union(() => {
			translate(60, 0)
			rotateX(PI / 2)
			cylinder(40, 12)
		})
		.subtract(() => {
			translate(-60, 0)
			rotateX(PI / 2)
			cylinder(20, 50)
		})
		.subtract(() => {
			translate(60, 0)
			rotateX(PI / 2)
			cylinder(20, 50)
		})
		.done()

	const innerBox = roundedCube(300 - 5, 300 / 4.25 * 2.75 - 5, 15, 5)
	cassetteInside = csg(() => model(innerBox))
		.subtract(() => box(300 - 15, 300 / 4.25 * 2.75 - 15, 15))
		.union(() => {
			translate(-60, 0)
			rotateX(PI / 2)
			cylinder(20, 15)
		})
		.subtract(() => {
			translate(-60, 0)
			rotateX(PI / 2)
			cylinder(17, 15)
		})
		.union(() => {
			translate(60, 0)
			rotateX(PI / 2)
			cylinder(20, 15)
		})
		.subtract(() => {
			translate(60, 0)
			rotateX(PI / 2)
			cylinder(17, 15)
		})
		.union(() => box(200, 100, 15))
		.subtract(() => box(200 - 10, 100 - 10, 15))
		.union(() => {
			translate(0, 75)
			box(150, 30, 15)
		})
		.subtract(() => {
			translate(-50, 80)
			rotateX(PI / 2)
			cylinder(7, 15)
		})
		.subtract(() => {
			translate(50, 80)
			rotateX(PI / 2)
			cylinder(7, 15)
		})
		.subtract(() => {
			translate(-30, 75)
			rotateX(PI / 2)
			cylinder(5, 15)
		})
		.subtract(() => {
			translate(30, 75)
			rotateX(PI / 2)
			cylinder(5, 15)
		})
		.done()

	gear = csg(() => {
			rotateX(PI / 2)
			cylinder(20, 10)
		})
		.subtract(() => {
			rotateX(PI / 2)
			cylinder(15, 10)
		})
		.union(() => {
			for (let i = 0; i < 8; i++) {
				push()
				rotate(i / 8 * TWO_PI)
				translate(0, 15)
				box(5, 5, 10)
				pop()
			}
		})
		.done()
}

function draw() {
	background('#ed225d')
	orbitControl()

	push()
	noStroke()
	ambientLight(200)
	let l = 150
	directionalLight(l, l, l, 0, 2, 1)
	directionalLight(l, l, l, -0.2, 0.5, 1)
	specularMaterial(255)
	shininess(100)
	fill('#111')
	scale(max(width / 200, height / 200))
	rotate(PI * 0.2)
	rotateX(-PI * 0.05)
	shader(tapeShader)
	model(ribbon)
	pop()

	push()
	rotateY(PI * 0.05 * sin(millis() * 0.001))
	rotateX(PI * 0.01 * sin(millis() * 0.0008))
	ambientLight(200)
	l = 100
	directionalLight(l, l, l, 0, 0.15, -1)
	directionalLight(l, l, l, -0.2, 0.5, -1)
	translate(0, 0, 100)
	rotateX(PI * 0.05)
	rotateY(PI * 0.05)
	noStroke()
	specularMaterial(255)
	shininess(300)

	fill(50)
	model(spools)

	push()
	fill('#FFC107')
	for (const side of [-1, 1]) {
		push()
		translate(side * 60, 0)
		model(gear)
		pop()
	}
	pop()

	drawTwoSided(() => {
		drawingContext.disable(drawingContext.DEPTH_TEST)
		fill(255, 20)
		shader(plastic)
		model(cassetteInside)
		model(cassette)
		drawingContext.enable(drawingContext.DEPTH_TEST)
	})
	push()
	translate(0, -70, 11)
	imageMode(CENTER)
	image(label, 0, 0)
	pop()
	pop()
}

function roundedCube(w, h, d, r) {
  const slices = []
  const n = max(1, round(TWO_PI * r / 4 * 0.5))

  const times = (n) => {
    let arr = []
    for (let i = 0; i < n; i++) {
      arr.push(i)
    }
    return arr
  }

  const makeSlice = (z, sr) => {
    return [
      ...times(n+1).map(i => createVector(-w/2, -h/2, z).add(sr*cos(i/n*HALF_PI+PI), sr*sin(i/n*HALF_PI+PI), 0)),
      ...times(n+1).map(i => createVector(w/2, -h/2, z).add(sr*cos(i/n*HALF_PI+PI*3/2), sr*sin(i/n*HALF_PI+PI*3/2), 0)),
      ...times(n+1).map(i => createVector(w/2, h/2, z).add(sr*cos(i/n*HALF_PI), sr*sin(i/n*HALF_PI), 0)),
      ...times(n+1).map(i => createVector(-w/2, h/2, z).add(sr*cos(i/n*HALF_PI+PI/2), sr*sin(i/n*HALF_PI+PI/2), 0)),
    ]
  }
  const makeSliceCenters = () => {
    return [
      ...times(n+1).map(i => createVector(-w/2, -h/2, 0)),
      ...times(n+1).map(i => createVector(w/2, -h/2, 0)),
      ...times(n+1).map(i => createVector(w/2, h/2, 0)),
      ...times(n+1).map(i => createVector(-w/2, h/2, 0)),
    ]
  }
  const sliceCenters = makeSliceCenters()

  const numSlices = n * 2 + 1
  for (let i = 0; i < numSlices; i++) {
    const z = map(i, 0, numSlices-1, -r, r)
    const fromCenter = map(abs(i - (numSlices-1)/2), 0, (numSlices-1)/2, 0, 1)
    const sr = lerp(sqrt(1 - fromCenter * fromCenter) * r, r, 0.05)
    slices.push(makeSlice(z, sr))
    sliceCenters.push(makeSliceCenters())
  }
  const sliceNormals = slices.map((slice) => {
    return slice.map((v, i) => {
      return v.copy().sub(sliceCenters[i]).normalize()
    })
  })
  const ptsPerSlice = slices[0].length
  const sliceIndices = []
  const mid = floor(numSlices/2)
  for (let i = 0; i <= mid; i++) {
    var off = -d/2
    sliceIndices.push({ i, off, idx: sliceIndices.length })
  }
  for (let i = mid; i < slices.length; i++) {
    var off = d/2
    sliceIndices.push({ i, off, idx: sliceIndices.length })
  }

  const g = buildGeometry(() => {
    for (const { idx } of sliceIndices.slice(0, -1)) {
      beginShape(QUAD_STRIP)
      for (let j = 0; j <= ptsPerSlice; j++) {
        for (const iOff of [0, 1]) {
          const { i, off } = sliceIndices[idx + iOff]
          const slice = slices[i]
          const pt = slice[j % slice.length]
          var n = sliceNormals[i][j % slice.length]
          normal(n.x, n.y, n.z)
          vertex(pt.x, pt.y, pt.z + off)
        }
      }
      endShape()
    }
    for (const face of [slices.at(-1).slice()]) {
      beginShape()
      for (const pt of face) {
        normal(0, 0, Math.sign(pt.z))
        vertex(pt.x, pt.y, pt.z + Math.sign(pt.z) * d/2)
      }
      endShape(CLOSE)
    }
  })

  const other = buildGeometry(() => {
    for (const face of [slices[0]]) {
      beginShape()
      for (const pt of face) {
        normal(0, 0, Math.sign(pt.z))
        vertex(pt.x, pt.y, pt.z + Math.sign(pt.z) * d/2)
      }
      endShape(CLOSE)
    }
  })

  var off = g.vertices.length
  g.vertices.push(...other.vertices)
  g.vertexNormals.push(...other.vertexNormals)
  g.uvs.push(...other.uvs)
  g.faces.push(...other.faces.map(f => f.map(i => i + off).reverse()))
  g.vertexColors.push(...other.vertexColors)

//   g.computeNormals(SMOOTH)
  return g
}

